STORY = [('kaiwen', '有个特别重要的事我跟你说，你要是真的想好好相处的话，工作上别走太近。', "Let me tell you something crucial: if you truly want things to go well with her, don't work too closely together.", [(499, '重要的事'), (500, '我跟你说'), (502, '好好相处的话'), (503, '工作上别走太近')], ''), ('chun_yuqiao', '什么意思？', 'What do you mean by that?', [(504, '什么意思')], ''), ('kaiwen', '兔子不吃窝边草，明白吗？你要是天天上班下班跟她见面，新鲜感没有了。', "A smart rabbit doesn't graze right by its burrow, get it? If you see her at work every single day, all the spark disappears.", [(505, '兔子不吃窝边草'), (506, '明白吗'), (508, '你要是天天上班下班'), (509, '跟她见面'), (510, '新鲜感没有了')], ''), ('kaiwen', '办公室恋情多有不便。以小谷的资质，你把她调到二部，独当一面完全没问题啊。', "Office romances bring endless headaches. With Xiaogu's talent, transferring her to Unit Two to lead projects on her own would work great.", [(528, '办公室恋情多有不便'), (533, '以小谷的资质'), (534, '你把她调到二部'), (535, '完全没问题啊')], ''), ('chun_yuqiao', '二部？麻烦你能不能先出去一会儿？', 'Unit Two? Could you do me a favor and step outside for a moment?', [(538, '二部'), (551, '麻烦你能不能'), (552, '先出去一会儿')], ''), ('kaiwen', '行。', 'Alright.', [(554, '行')], ''), ('chun_yuqiao', '她研究十二歌王很久了，其实在改版的思路上理解非常深。', 'She has studied Twelve Singers for a long time and understands our revamp vision deeply.', [(560, '研究十二歌王很久了'), (561, '其实在改版的思路上'), (562, '理解非常深')], ''), ('chun_yuqiao', '如果现在这个时候把她调到二部去，对她的打击会很大。', 'If I transfer her away to Unit Two at a moment like this, it will be a huge blow to her.', [(563, '如果现在这个时候'), (564, '调到二部去'), (565, '打击会很大')], ''), ('chun_yuqiao', '我本来是想着可以把她留在总编室，早点转正。', "Originally I was planning to keep her in the chief editor's office and make her permanent early.", [(566, '我本来是想着'), (567, '可以把她留在总编室'), (568, '早点转正')], ''), ('chun_yuqiao', '但是如果现在另有安排，是不是太自私啊？', "If I make other arrangements for my own sake now, wouldn't that be far too selfish?", [(569, '但是如果现在另有安排'), (570, '是不是太自私啊')], ''), ('bu_xiaogu', '不好意思，我昨天晚上过生日，所以睡得晚，起得就晚了点。', "I'm so sorry — I celebrated my birthday last night, so I slept late and woke up a little behind.", [(574, '不好意思'), (575, '我昨天晚上过生日'), (576, '所以睡得晚'), (577, '起得就晚了点')], ''), ('bu_xiaogu', '刚才秦箫跟我说，电视台的邓主任要开那个改版讨论会，正在会议室等您呢。', 'Qin Xiao just told me the network director is here for the revamp discussion and waiting for you in the conference room.', [(578, '跟我说'), (579, '邓主任'), (580, '开那个改版讨论会'), (581, '正在会议室等您呢')], '')]
WALK = [(0, None, '"Let me tell you something crucial: if you truly want things to go well with her, don\'t work too closely together."'), (1, None, "'What do you mean by that?'"), (2, None, '"A smart rabbit doesn\'t graze right by its burrow, get it? If you see her at work every single day, all the spark disappears."'), (3, None, '"Office romances bring endless headaches. With Xiaogu\'s talent, transferring her to Unit Two to lead projects on her own would work great."'), (4, None, "'Unit Two? Could you do me a favor and step outside for a moment?'"), (5, None, "'Alright.'"), (6, None, "'She has studied Twelve Singers for a long time and understands our revamp vision deeply.'"), (7, None, "'If I transfer her away to Unit Two at a moment like this, it will be a huge blow to her.'"), (8, None, '"Originally I was planning to keep her in the chief editor\'s office and make her permanent early."'), (9, None, '"If I make other arrangements for my own sake now, wouldn\'t that be far too selfish?"'), (10, None, '"I\'m so sorry — I celebrated my birthday last night, so I slept late and woke up a little behind."'), (11, None, "'Qin Xiao just told me the network director is here for the revamp discussion and waiting for you in the conference room.'")]
